1153	///|
1154	async fn execute_inner(mode : String) -> Unit {
1155	  notify(mode)
1156	  if mode == "create" ||
1157	    mode == "resume" ||
1158	    mode == "recover" ||
1159	    mode == "restart" {
1160	    save_diagnostic(
1161	      "connection-budget",
1162	      "selected",
1163	      timeout_ms=connection_timeout_ms(),
1164	    )
1165	  }
1166	  let started = @env.now()
1167	  let (state, previous, deadline) = if mode == "create" {
1168	    let (state, expires) = create_state()
1169	    (state, Json::null(), Some(expires))
1170	  } else {
1171	    let (state, previous) = if mode == "recover" || mode == "restart" {
1172	      connection_timeout(started + connection_timeout_ms().to_uint64(), async fn() {
1173	        lifecycle_state(mode)
1174	      })
1175	    } else {
1176	      lifecycle_state(mode)
1177	    }
1178	    (
1179	      state,
1180	      previous,
1181	      if mode == "recover" || mode == "restart" {
1182	        Some(started + connection_timeout_ms().to_uint64())
1183	      } else {
1184	        None
1185	      },
1186	    )
1187	  }
1188	  let operation = if mode == "resume" || mode == "suspend" || mode == "destroy" {
1189	    Some(connection_operation_lock(state))
1190	  } else {
1191	    None
1192	  }
1193	  defer (if operation is Some(lock) { lock.close() })
1194	  if mode == "resume" {
1195	    guard workspace(state) is Some(current) &&
1196	      field(current, "uid") == field(state, "workspaceUid") else {
1197	      raise AdapterError("Workspace missing or replaced before resume")
1198	    }
1199	    unpause_tunnel(state)
1200	  }
1201	  match mode {
1202	    "create" => {
1203	      create_recording.phase = "connection"
1204	      errdefer discard_created_workspace(state)
1205	      connection_timeout(deadline.unwrap(), async fn() {
1206	        codex_addon(state)
1207	        emit_connection(state, true, deadline?)
1208	      })
1209	    }
1210	    "resume" => {
1211	      ignore(
1212	        devsy(
1213	          state,
1214	          [
1215	            "--result-format",
1216	            "json",
1217	            "workspace",
1218	            "up",
1219	            required(state, "workspaceId"),
1220	            "--ide-launch",
1221	            "skip",
1222	          ] +
1223	          orca_storage_args(state),
1224	          "workspace-resume",
1225	        ),
1226	      )
1227	      let expires = connection_deadline()
1228	      idle_reset(state, "workspace_resumed")
1229	      connection_timeout(expires, async fn() {
1230	        let port = if required(state, "connection") == "orca-server" {
1231	          Some(reserve_server_port(state))
1232	        } else {
1233	          None
1234	        }
1235	        ensure_ssh_worker(state, port, deadline=expires)
1236	        codex_addon(state)
1237	        if required(state, "connection") == "orca-server" {
1238	          ignore(recover_server(state))
1239	        }
1240	        emit_connection(state, false, existing=previous, deadline=expires)
1241	      })
1242	    }
1243	    "recover" | "restart" => {
1244	      recover_connection(state, restart=mode == "restart", deadline?)
1245	      let connection = field(previous, "connection").unwrap()
1246	      write_connection(state, connection)
1247	    }
1248	    "suspend" => {
1249	      pause_tunnel(state)
1250	      defer unpause_tunnel(state)
1251	      stop_workspace(state)
1252	    }
1253	    "destroy" => {
1254	      pause_tunnel(state)
1255	      errdefer unpause_tunnel(state)
1256	      ignore(
1257	        devsy(
1258	          state,
1259	          [
1260	            "workspace",
1261	            "delete",
1262	            required(state, "workspaceId"),
1263	            "--ignore-not-found",
1264	          ],
1265	          "workspace-delete",
1266	        ),
1267	      )
1268	      cleanup_orca_volume(state)
1269	      if field(state, "tunnelDirectory") is Some(Json::String(directory)) {
1270	        for name in ["server-update-pending", "server-update-complete"] {
1271	          if @fs.exists(directory + "/" + name) {
1272	            @fs.remove(directory + "/" + name)
1273	          }
1274	        }
1275	      }
1276	      close_tunnel(state)
1277	    }
1278	    _ => raise AdapterError("Unknown command")
1279	  }
1280	  save_diagnostic(mode, "success")
1281	  progress_message(mode + ": done (" + progress_timing(progress_started) + ")")
1282	}
