1294	///|
1295	pub async fn execute(mode : String) -> Unit {
1296	  let mut failure_recorded = false
1297	  errdefer (if !failure_recorded && @async.is_being_cancelled() {
1298	    @async.protect_from_cancel(async fn() {
1299	      save_diagnostic(mode, "cancelled", error_type="cancelled")
1300	    })
1301	  })
1302	  execute_inner(mode) catch {
1303	    InvalidConfig(message) => {
1304	      let detail = diagnostic_error(InvalidConfig(message))
1305	      progress_message(detail + " (" + progress_timing(progress_started) + ")")
1306	      save_command_failure(mode, InvalidConfig(message))
1307	      failure_recorded = true
1308	      raise InvalidConfig(message)
1309	    }
1310	    AdapterError(message) => {
1311	      let detail = diagnostic_error(AdapterError(message))
1312	      progress_message(detail + " (" + progress_timing(progress_started) + ")")
1313	      save_command_failure(mode, AdapterError(message))
1314	      failure_recorded = true
1315	      raise AdapterError(message)
1316	    }
1317	    error => {
1318	      progress_message(
1319	        mode + ": failed (" + progress_timing(progress_started) + ")",
1320	      )
1321	      save_command_failure(mode, error)
1322	      failure_recorded = true
1323	      raise AdapterError(
1324	        mode +
1325	        " failed: unexpected runtime error; diagnostic run " +
1326	        recording_run_id,
1327	      )
1328	    }
1329	  }
1330	}
