167	///|
168	fn terminal_text(text : String) -> String? {
169	  let output = @buffer.Buffer(size_hint=256)
170	  let mut state = 0
171	  for c in text.iter() {
172	    match state {
173	      0 =>
174	        if c == '\u001b' {
175	          state = 1
176	        } else if c.to_int() < 32 && c != '\t' {
177	          return None
178	        } else {
179	          output.write_char_utf8(c)
180	        }
181	      1 =>
182	        if c == '[' {
183	          state = 2
184	        } else if c == ']' {
185	          state = 3
186	        } else {
187	          return None
188	        }
189	      2 => if c >= '@' && c <= '~' { state = 0 }
190	      3 => if c == '\u0007' { state = 0 } else if c == '\u001b' { state = 4 }
191	      _ => if c == '\\' { state = 0 } else { state = 3 }
192	    }
193	  }
194	  if state != 0 {
195	    None
196	  } else {
197	    Some(@utf8.decode_lossy(output.to_bytes()))
198	  }
199	}
