 67	///|
 68	fn diagnostic_json(
 69	  value : Json,
 70	  environment : Map[String, String],
 71	  truncated : Ref[Bool],
 72	  depth : Int32,
 73	) -> Json {
 74	  if depth >= 64 {
 75	    truncated.val = true
 76	    return Json::string("[nested evidence omitted]")
 77	  }
 78	  match value {
 79	    Json::Object(values) => {
 80	      let result = Json::empty_object()
 81	      for name, item in values {
 82	        let key = name.to_lower().replace_all(old="_", new="")
 83	        set_field(
 84	          result,
 85	          name,
 86	          if credential_field(name) || key == "pairingcode" {
 87	            Json::string("[redacted]")
 88	          } else {
 89	            diagnostic_json(item, environment, truncated, depth + 1)
 90	          },
 91	        )
 92	      }
 93	      result
 94	    }
 95	    Json::Array(values) =>
 96	      Json::array(
 97	        values.map(item => {
 98	          diagnostic_json(item, environment, truncated, depth + 1)
 99	        }),
100	      )
101	    Json::String(text) => {
102	      let safe = diagnostic_text(text, environment~)
103	      if safe.has_suffix("\n[error details incomplete or truncated]") {
104	        truncated.val = true
105	      }
106	      Json::string(safe)
107	    }
108	    _ => value
109	  }
110	}
