423	fn diagnostic_error(
424	  error : Error,
425	  environment? : Map[String, String],
426	) -> String {
427	  let (message, omitted) = match error {
428	    AdapterError(detail) => (detail, false)
429	    InvalidConfig(detail) => (detail, false)
430	    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
431	    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
432	    @json.InvalidNumber(position, _) =>
433	      (
434	        "Invalid JSON number at line \{position.line}, column \{position.column}; value omitted",
435	        true,
436	      )
437	    _ => (error.to_string(), false)
438	  }
439	  diagnostic_text(message, environment?, omitted~)
