442	///|
443	fn diagnostic_text(
444	  message : String,
445	  environment? : Map[String, String],
446	  omitted~ : Bool = false,
447	  protected_values? : Array[String],
448	  incomplete_final_line~ : Bool = false,
449	) -> String {
450	  let progress = Progress::new("diagnostic-error", environment?)
451	  if protected_values is Some(values) {
452	    for value in values {
453	      if value != "" {
454	        progress.secrets.push(value)
455	      }
456	    }
457	    progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
458	  }
459	  let lines = []
460	  let mut incomplete = omitted
461	  let source_lines = message.split("\n").to_array()
462	  for index in 0..<source_lines.length() {
463	    let line = source_lines[index]
464	    if lines.length() == 8 {
465	      incomplete = true
466	      ignore(lines.remove(1))
467	    }
468	    let truncated = line.length() > 1024
469	    let bounded = if truncated {
470	      incomplete = true
471	      line[:1024].to_owned()
472	    } else {
473	      line.to_owned()
474	    }
475	    let bounded = if truncated ||
476	      (incomplete_final_line && index == source_lines.length() - 1) {
477	      diagnostic_partial_secret(bounded, progress.secrets)
478	    } else {
479	      bounded
480	    }
481	    match progress.safe_message(bounded) {
482	      Some(safe) => lines.push(safe)
483	      None => {
484	        incomplete = true
485	        lines.push("[unavailable]")
486	      }
487	    }
488	  }
489	  if (incomplete || progress.details_truncated) &&
490	    lines.last() != Some("[error details incomplete or truncated]") {
491	    lines.push("[error details incomplete or truncated]")
492	  }
493	  lines.join("\n")
494	}
