496	///|
497	fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
498	  let chars = text.iter().to_array()
499	  let mut boundary = chars.length()
500	  for secret in secrets {
501	    let value = secret.iter().to_array()
502	    if value.length() == 0 || text.has_suffix(secret) {
503	      continue
504	    }
505	    let limit = if value.length() - 1 < boundary {
506	      value.length() - 1
507	    } else {
508	      boundary
509	    }
510	    if limit == 0 {
511	      continue
512	    }
513	    let prefixes = FixedArray::make(limit, 0)
514	    let mut matched = 0
515	    for index in 1..<limit {
516	      while matched > 0 && value[matched] != value[index] {
517	        matched = prefixes[matched - 1]
518	      }
519	      if value[matched] == value[index] {
520	        matched += 1
521	      }
522	      prefixes[index] = matched
523	    }
524	    matched = 0
525	    for index in 0..<boundary {
526	      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
527	        matched = prefixes[matched - 1]
528	      }
529	      if matched < limit && value[matched] == chars[index] {
530	        matched += 1
531	      }
532	    }
533	    boundary -= matched
534	  }
535	  if boundary == chars.length() {
536	    text
537	  } else {
538	    character_text(chars, 0, boundary) + "[redacted]"
539	  }
540	}
