608	fn diagnostic_output(
609	  output : Bytes,
610	  environment : Map[String, String],
611	  protected_input? : String,
612	  omitted~ : Bool = false,
613	) -> String? {
614	  if output.length() == 0 {
615	    return None
616	  }
617	  let safeguards : DiagnosticProtectedValues = {
618	    values: [],
619	    visited: 0,
620	    incomplete: false,
621	  }
622	  if protected_input is Some(input) {
623	    diagnostic_protected_values(@json.parse(input), safeguards) catch {
624	      _ => safeguards.incomplete = true
625	    }
626	  }
627	  if safeguards.incomplete {
628	    return Some(
629	      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
630	    )
631	  }
632	  let limit = if output.length() > 8192 { 8192 } else { output.length() }
633	  let incomplete = omitted || limit < output.length()
634	  Some(
635	    diagnostic_text(
636	      @utf8.decode_lossy(output[:limit]),
637	      environment~,
638	      omitted=incomplete,
639	      protected_values=safeguards.values,
640	      incomplete_final_line=incomplete && output[limit - 1] != b'\n',
641	    ),
642	  )
643	}
