645	///|
646	async fn diagnostic_capture(
647	  reader : @process.ReadFromProcess,
648	  limit : Int32,
649	) -> (Bytes, Bool) {
650	  let output = @buffer.Buffer(size_hint=if limit < 4096 { limit } else { 4096 })
651	  let mut truncated = false
652	  while reader.read_some(max_len=4096) is Some(chunk) {
653	    let remaining = limit - output.length()
654	    let count = if chunk.length() < remaining {
655	      chunk.length()
656	    } else {
657	      remaining
658	    }
659	    if count > 0 {
660	      output.write_bytes(chunk[:count])
661	    }
662	    if count < chunk.length() {
663	      truncated = true
664	    }
665	  }
666	  (output.to_bytes(), truncated)
667	}
