   113	async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
   114	  let length = if size > 262144L { 262144 } else { size.to_int() }
   115	  let bytes = FixedArray::make(length, b'\x00')
   116	  let read = file.read_at(bytes, position=size - length.to_int64())
   117	  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
   118	  let lines = text.split("\n").to_array()
   119	  let kept = FixedArray::make(lines.length(), false)
   120	  let mut remaining = 65536
   121	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
   122	    if i == 0 && size > length.to_int64() {
   123	      continue
   124	    }
   125	    let length = lines[i].length() + 1
   126	    if length <= remaining {
   127	      kept[i] = true
   128	      remaining -= length
   129	    }
   130	  }
   131	  remaining = 65536
   132	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
   133	    if kept[i] || (i == 0 && size > length.to_int64()) {
   134	      continue
   135	    }
   136	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
   137	    let failed = field(event, "errorType") is Some(_) ||
   138	      (match field(event, "status") {
   139	        Some(Json::String(status)) =>
   140	          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
   141	            status,
   142	          )
   143	        _ => false
   144	      })
   145	    let length = lines[i].length() + 1
   146	    if failed && length <= remaining {
   147	      kept[i] = true
   148	      remaining -= length
   149	    }
   150	  }
   151	  let result = @buffer.Buffer(size_hint=131072)
   152	  for i in 0..<lines.length() {
   153	    if kept[i] {
   154	      result.write_string_utf8(lines[i].to_owned() + "\n")
   155	    }
   156	  }
   157	  @utf8.decode_lossy(result.to_bytes())
   158	}
