549	///|
550	fn diagnostic_protected_values(
551	  value : Json,
552	  result : DiagnosticProtectedValues,
553	) -> Unit {
554	  if result.visited >= 4096 || result.values.length() >= 512 {
555	    result.incomplete = true
556	    return
557	  }
558	  result.visited += 1
559	  match value {
560	    Json::String(text) if text != "" => {
561	      result.values.push(text)
562	      for line in text.split("\n") {
563	        if line != "" && line.length() < text.length() {
564	          if result.values.length() >= 512 {
565	            result.incomplete = true
566	            return
567	          }
568	          result.values.push(line.to_owned())
569	        }
570	        for word in line.split(" ") {
571	          for part in word.split("=") {
572	            if part == "" || part.length() >= text.length() {
573	              continue
574	            }
575	            if result.values.length() >= 512 {
576	              result.incomplete = true
577	              return
578	            }
579	            result.values.push(part.to_owned())
580	          }
581	        }
582	      }
583	      let escaped = Json::string(text).stringify()
584	      if escaped.length() > 2 {
585	        let encoded = escaped[1:escaped.length() - 1].to_owned()
586	        if encoded != "" && encoded != text {
587	          if result.values.length() >= 512 {
588	            result.incomplete = true
589	            return
590	          }
591	          result.values.push(encoded)
592	        }
593	      }
594	    }
595	    Json::Array(values) =>
596	      for item in values {
597	        diagnostic_protected_values(item, result)
598	      }
599	    Json::Object(values) =>
600	      for _, item in values {
601	        diagnostic_protected_values(item, result)
602	      }
603	    _ => ()
604	  }
605	}
