119	///|
120	fn sensitive_name(name : String) -> Bool {
121	  let name = name.to_lower()
122	  [
123	    "password", "passwd", "token", "secret", "api_key", "apikey", "auth", "credential",
124	    "private_key", "access_key", "cookie", "fnox_age_key",
125	  ]
126	  .iter()
127	  .any(marker => name.contains(marker))
128	}
