130	///|
131	fn Progress::new(
132	  stage : String,
133	  environment? : Map[String, String],
134	  recording_override? : Bool,
135	) -> Progress {
136	  let secrets = []
137	  for name, value in environment.unwrap_or(@env.get_env_vars()) {
138	    if sensitive_name(name) && value != "" {
139	      secrets.push(value)
140	      // Multiline credentials must also be masked in line-oriented output.
141	      for part in value.split("\n") {
142	        if part.trim() != "" {
143	          secrets.push(part.to_owned())
144	        }
145	      }
146	    }
147	  }
148	  secrets.sort_by((a, b) => b.length().compare(a.length()))
149	  {
150	    stage,
151	    operations: {},
152	    builds: {},
153	    secrets,
154	    recording: recording_override.unwrap_or(
155	      environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
156	      Some("0"),
157	    ),
158	    phase_count: 0,
159	    private_key: false,
160	    classic_build: false,
161	    recent: [],
162	    failures: [],
163	    details_truncated: false,
164	  }
165	}
