370	///|
371	async fn Progress::line(
372	  self : Progress,
373	  line : String,
374	  statuses~ : Bool,
375	  messages~ : Bool,
376	) -> Unit {
377	  if line.trim() == "" {
378	    return
379	  }
380	  let event = @json.parse(line) catch { _ => Json::null() }
381	  if field(event, "kind") == Some(Json::string("status")) {
382	    if field(event, "state") == Some(Json::string("failed")) &&
383	      field(event, "error") is Some(error) {
384	      for name in ["message", "hint"] {
385	        if field(error, name) is Some(Json::String(text)) {
386	          self.message(
387	            text,
388	            debug=false,
389	            warning=true,
390	            emit=messages || statuses,
391	          )
392	        }
393	      }
394	    }
395	    if statuses || messages {
396	      self.status(event)
397	    }
398	    return
399	  }
400	  // Result envelopes and arbitrary structured responses are never log text.
401	  if field(event, "kind") == Some(Json::string("result")) {
402	    return
403	  }
404	  if event is Json::Object(_) {
405	    let kind = field(event, "kind")
406	    guard kind == None ||
407	      kind == Some(Json::string("log")) ||
408	      kind == Some(Json::string("error")) else {
409	      return
410	    }
411	    let message = match field(event, "msg") {
412	      Some(value) => Some(value)
413	      None => field(event, "message")
414	    }
415	    guard message is Some(Json::String(text)) else { return }
416	    let level = field(event, "level")
417	    self.message(
418	      text,
419	      debug=level == Some(Json::string("debug")) ||
420	        level == Some(Json::string("trace")),
421	      warning=kind == Some(Json::string("error")) ||
422	        level == Some(Json::string("warn")) ||
423	        level == Some(Json::string("error")),
424	      emit=messages || (statuses && kind != None),
425	    )
426	  } else {
427	    if event != Json::null() {
428	      return
429	    }
430	    // Malformed JSON and binary output are not a safe free-text fallback.
431	    let text = line.trim().to_owned()
432	    if text.has_prefix("{") || text.has_prefix("[") {
433	      self.details_truncated = true
434	      return
435	    }
436	    self.message(
437	      text,
438	      debug=text.contains(" DEBUG ") ||
439	        text.contains(" TRACE ") ||
440	        text.has_prefix("DEBUG ") ||
441	        text.has_prefix("TRACE "),
442	      warning=text.contains(" WARN ") ||
443	        text.contains(" ERROR ") ||
444	        text.has_prefix("WARN ") ||
445	        text.has_prefix("ERROR "),
446	      emit=messages,
447	    )
448	  }
449	}
