451	///|
452	async fn Progress::read_output(
453	  self : Progress,
454	  reader : @process.ReadFromProcess,
455	  capture~ : Bool,
456	  statuses~ : Bool = false,
457	  messages~ : Bool = false,
458	  raw_messages~ : Bool = false,
459	) -> String {
460	  let output = @buffer.Buffer(size_hint=4096)
461	  let pending = @buffer.Buffer(size_hint=4096)
462	  let mut oversized = false
463	  let mut tail = ""
464	  while reader.read_some(max_len=4096) is Some(chunk) {
465	    if capture {
466	      output.write_bytes(chunk)
467	    } else {
468	      tail += @utf8.decode_lossy(chunk)
469	      if tail.length() > 8192 {
470	        tail = tail[tail.length() - 8192:].to_owned()
471	      }
472	    }
473	    for byte in chunk {
474	      if byte == b'\n' || byte == b'\r' {
475	        if !oversized && pending.length() > 0 {
476	          let line = @utf8.decode(pending.to_bytes()) catch {
477	            _ => {
478	              self.details_truncated = true
479	              ""
480	            }
481	          }
482	          if raw_messages {
483	            self.message(line, debug=false, warning=true, emit=false)
484	          } else {
485	            self.line(line, statuses~, messages~)
486	          }
487	        }
488	        pending.reset()
489	        oversized = false
490	      } else if !oversized {
491	        if pending.length() == 65536 {
492	          pending.reset()
493	          oversized = true
494	          self.details_truncated = true
495	        } else {
496	          pending.write_byte(byte)
497	        }
498	      }
499	    }
500	  }

