 40	        home + "/Library/Application Support/orca"
 41	      } else {
 42	        @env.get_env_var("XDG_CONFIG_HOME")
 43	        .filter(p => p != "")
 44	        .unwrap_or(home + "/.config") +
 45	        "/orca"
 46	      },
 47	    )
 48	  let metadata = @json.parse(
 49	    @fs.read_file(user_data + "/orca-runtime.json").text(),
 50	  )
 51	  let pid = match field(metadata, "pid") {
 52	    Some(Json::Number(value, ..)) if value > 1 && value == value.trunc() =>
 53	      value.to_int()
 54	    _ => raise AdapterError("Invalid host Orca runtime PID")
 55	  }
 56	  let executables = [settings_executable(pid)]
 57	  if @async.platform is Linux {
 58	    let args = @fs.read_file("/proc/\{pid}/cmdline")
 59	      .text()
 60	      .split("\u0000")
 61	      .to_array()
 62	    for i = 0; i + 1 < args.length(); i = i + 1 {
 63	      if args[i] == "--spawner-exec-path" {
 64	        executables.push(args[i + 1].to_owned())
 65	      }
 66	    }
 67	  }
 68	  for executable in executables {
 69	    let parent = settings_parent(executable)
 70	    for
 71	      resources in [
 72	        parent + "/resources",
 73	        settings_parent(parent) + "/Resources",
 74	      ] {
 75	      if @fs.exists(
 76	          resources +
 77	          "/app.asar.unpacked/out/main/persistence/profile-state/profile-state-domain-reader.js",
 78	        ) {
 79	        return (executable, resources, user_data)
 80	      }
 81	    }
 82	  }
 83	  raise AdapterError("Cannot locate the running host Orca resources")
 84	}
