  1	///|
  2	fn credential_field(name : String) -> Bool {
  3	  let name = name
  4	    .trim_start(chars="-")
  5	    .to_owned()
  6	    .to_lower()
  7	    .replace_all(old="-", new="_")
  8	  [
  9	    "auth", "authorization", "proxy_authorization", "cookie", "set_cookie", "password",
 10	    "passwd", "token", "access_token", "accesstoken", "refresh_token", "refreshtoken",
 11	    "id_token", "api_key", "apikey", "x_api_key", "credential", "credentials", "secret",
 12	    "client_secret", "clientsecret", "private_key", "privatekey", "aws_secret_access_key",
 13	    "azure_storage_key", "docker_auth_config", "signature", "sig", "x_amz_signature",
 14	    "x_amz_security_token", "x_goog_signature",
 15	  ].contains(name) ||
 16	  [
 17	    "_auth", "_password", "_passwd", "_token", "_secret", "_api_key", "_private_key",
 18	  ]
 19	  .iter()
 20	  .any(suffix => name.has_suffix(suffix))
 21	}
 22	
 23	///|
 24	fn credential_word(c : Char) -> Bool {
 25	  (c >= 'a' && c <= 'z') ||
 26	  (c >= 'A' && c <= 'Z') ||
 27	  (c >= '0' && c <= '9') ||
 28	  c == '_' ||
 29	  c == '-'
 30	}
 31	
 32	///|
 33	fn credential_space(c : Char) -> Bool {
 34	  c == ' ' || c == '\t'
 35	}
 36	
 37	///|
 38	fn credential_end(c : Char) -> Bool {
 39	  credential_space(c) ||
 40	  [',', ';', '&', '#', '"', '\'', '}', ']', '<', '>'].contains(c)
 41	}
 42	
 43	///|
 44	fn character_text(chars : Array[Char], start : Int32, end : Int32) -> String {
 45	  let buffer = @buffer.Buffer(size_hint=end - start)
 46	  for i in start..<end {
 47	    buffer.write_char_utf8(chars[i])
 48	  }
 49	  @utf8.decode_lossy(buffer.to_bytes())
 50	}
 51	
 52	///|
 53	fn credential_hex(c : Char) -> Int32? {
 54	  match c {
 55	    '0'..<='9' => Some(c.to_int() - '0'.to_int())
 56	    'a'..<='f' => Some(c.to_int() - 'a'.to_int() + 10)
 57	    'A'..<='F' => Some(c.to_int() - 'A'.to_int() + 10)
 58	    _ => None
 59	  }
 60	}
 61	
 62	///|
 63	fn credential_parameter(name : String) -> String {
 64	  let chars = name.iter().to_array()
 65	  let buffer = @buffer.Buffer(size_hint=name.length())
 66	  let mut i = 0
 67	  while i < chars.length() {
 68	    if chars[i] == '%' &&
 69	      i + 2 < chars.length() &&
 70	      credential_hex(chars[i + 1]) is Some(hi) &&
 71	      credential_hex(chars[i + 2]) is Some(lo) {
 72	      buffer.write_char_utf8((hi * 16 + lo).unsafe_to_char())
 73	      i += 3
 74	    } else {
 75	      buffer.write_char_utf8(chars[i])
 76	      i += 1
 77	    }
 78	  }
 79	  @utf8.decode_lossy(buffer.to_bytes())
 80	}
