282	///|
283	fn redact_short_secret(text : String, secret : String) -> String {
284	  let chars = text.iter().to_array()
285	  let value = secret.iter().to_array()
286	  let result = @buffer.Buffer(size_hint=text.length())
287	  let mut i = 0
288	  while i < chars.length() {
289	    let mut matches = value.length() > 0 && i + value.length() <= chars.length()
290	    if matches {
291	      for j in 0..<value.length() {
292	        if chars[i + j] != value[j] {
293	          matches = false
294	          break
295	        }
296	      }
297	    }
298	    if matches &&
299	      (i == 0 || !credential_word(chars[i - 1])) &&
300	      (
301	        i + value.length() == chars.length() ||
302	        !credential_word(chars[i + value.length()])
303	      ) {
304	      result.write_string_utf8("[redacted]")
305	      i += value.length()
306	    } else {
307	      result.write_char_utf8(chars[i])
308	      i += 1
309	    }
310	  }
311	  @utf8.decode_lossy(result.to_bytes())
