290	    })
291	    None
292	  } catch {
293	    error => Some(error)
294	  }
295	  if failure is Some(error) {
296	    if @async.is_being_cancelled() {
297	      raise error
298	    }
299	    let protected_input = Json::array(secrets.map(Json::string)).stringify()
300	    let detail = diagnostic_output(
301	      captured.to_bytes(),
302	      @env.get_env_vars(),
303	      protected_input~,
304	      omitted=incomplete.val || !finished.val,
305	    )
306	    raise AdapterError(
307	      diagnostic_error(error) +
308	      detail
309	      .map(value => "\nCodex app-server stderr: " + value)
310	      .unwrap_or(
311	        if finished.val {
312	          ""
313	        } else {
314	          "\n[Codex app-server stderr incomplete]"
315	        },
