101	async fn settings_process(
102	  program : String,
103	  args : Array[String],
104	  environment~ : Map[String, String],
105	  input? : String,
106	) -> String {
107	  let (stdin, writer) = @process.write_to_process()
108	  defer writer.close()
109	  @async.with_task_group(async fn(group) {
110	    let output = group.spawn(async fn() {
111	      diagnostic_process_output(
112	        program,
113	        args,
114	        environment~,
115	        stdin~,
116	        stdout_limit=4194304,
117	        stderr_limit=8192,
118	      )
119	    })
120	    if input is Some(value) {
121	      writer.write(value)
122	    }
123	    writer.close()
124	    let (status, stdout, stdout_truncated, stderr, stderr_truncated) = output.wait()
125	    guard status == 0 else {
126	      let mut phase = "process"
127	      let mut code = "process_exit"
128	      let mut detail = diagnostic_output(
129	        stderr,
130	        environment,
131	        protected_input?=input,
132	        omitted=stderr_truncated,
133	      )
134	      if !stderr_truncated {
135	        try {
136	          let error = @json.parse(@utf8.decode(stderr))
137	          let reported_phase = required(error, "phase")
138	          let reported_code = required(error, "code")
139	          if [
140	              "load", "read", "normalize", "input", "profile", "write", "verify",
141	            ].contains(reported_phase) &&
142	            ["EACCES", "ENOENT", "EBUSY", "ENOSPC", "INCOMPATIBLE", "INVALID"].contains(
143	              reported_code,
144	            ) {
145	            phase = reported_phase
146	            code = reported_code
147	            let kind = match field(error, "kind") {
148	              Some(Json::String(value)) if [
149	                  "Error", "TypeError", "SyntaxError", "ReferenceError", "RangeError",
150	                  "AssertionError", "URIError",
151	                ].contains(value) => Some(value)
152	              _ => None
153	            }
154	            let native_code = match field(error, "nativeCode") {
155	              Some(Json::String(value)) if value.length() > 0 &&
156	                value.length() <= 64 &&
157	                value
158	                .iter()
159	                .all(c => {
160	                  (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
161	                }) => Some(value)
162	              _ => None
163	            }
164	            detail = if kind is Some(kind) {
165	              Some(
166	                kind +
167	                native_code.map(value => " (" + value + ")").unwrap_or(""),
168	              )
169	            } else {
170	              None
171	            }
172	          }
173	        } catch {
174	          _ => ()
175	        }
