146	async fn read_codex_auth(home : String) -> CodexAuth {
147	  guard @fs.file_size(home + "/auth.json") <= 65536L else {
148	    raise AdapterError("Invalid Codex auth size")
149	  }
150	  let source = @fs.read_file(home + "/auth.json")
151	  guard source.binary().length() <= 65536 else {
152	    raise AdapterError("Invalid Codex auth size")
153	  }
154	  let auth = @json.parse(source.text())
155	  guard (
156	      field(auth, "OPENAI_API_KEY") == None ||
157	      field(auth, "OPENAI_API_KEY") == Some(Json::null())
158	    ) &&
159	    (
160	      field(auth, "auth_mode") == None ||
161	      field(auth, "auth_mode") == Some(Json::string("chatgpt"))
162	    ) else {
163	    raise AdapterError("Unsupported Codex auth mode")
164	  }
165	  guard field(auth, "tokens") is Some(tokens) else {
166	    raise AdapterError("Missing Codex auth tokens")
167	  }
168	  let access = required(tokens, "access_token")
169	  let secrets = [access]
170	  for name in ["id_token", "refresh_token"] {
171	    if field(tokens, name) is Some(Json::String(value)) && value != "" {
172	      secrets.push(value)
173	    }
174	  }
175	  let segments = access.split(".").to_array()
176	  guard segments.length() == 3 else {
177	    raise AdapterError("Invalid access token")
178	  }
179	  let encoded = segments[1]
180	    .to_owned()
181	    .replace_all(old="-", new="+")
182	    .replace_all(old="_", new="/")
183	  let padding = (4 - encoded.length() % 4) % 4
184	  let claims = @json.parse(
185	    @utf8.decode(@base64.decode(encoded + "=".repeat(padding))),
186	  )
187	  guard field(claims, "exp") is Some(Json::Number(expiry, ..)) else {
188	    raise AdapterError("Invalid access token expiry")
189	  }
190	  { access, account: required(tokens, "account_id"), expiry, secrets, }
191	}
