 857	///|
 858	fn diagnostic_value(value : String?, kind : DiagnosticValueKind) -> Json {
 859	  match value {
 860	    None => { "state": "unset" }
 861	    Some("") => { "state": "empty" }
 862	    Some(text) => {
 863	      let valid = match kind {
 864	        Commit => valid_commit(text)
 865	        Workspace => valid_workspace_id(text)
 866	        Identity => text.length() <= 128 && valid_context(text)
 867	        RefName => diagnostic_ref(text)
 868	      }
 869	      let credential_form = text
 870	        .split("/")
 871	        .iter()
 872	        .any(part => {
 873	          [
 874	            "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "glpat-", "sk-",
 875	            "eyJ",
 876	          ]
 877	          .iter()
 878	          .any(prefix => part.has_prefix(prefix))
 879	        })
 880	      if valid && !credential_form {
 881	        { "state": "valid", "value": text }
 882	      } else {
 883	        { "state": "invalid" }
 884	      }
 885	    }
 886	  }
 887	}
