 889	///|
 890	// A recording grammar, never a replacement for checkout validation. Excludes
 891	// URLs, credential forms, control characters and Git's invalid ref syntax.
 892	fn diagnostic_ref(text : String) -> Bool {
 893	  text.length() <= 1024 &&
 894	  !text.has_prefix("-") &&
 895	  !text.contains("..") &&
 896	  text
 897	  .split("/")
 898	  .iter()
 899	  .all(part => {
 900	    part != "" &&
 901	    !part.has_prefix(".") &&
 902	    !part.has_suffix(".") &&
 903	    !part.has_suffix(".lock")
 904	  }) &&
 905	  text
 906	  .iter()
 907	  .all(c => {
 908	    (c >= 'a' && c <= 'z') ||
 909	    (c >= 'A' && c <= 'Z') ||
 910	    (c >= '0' && c <= '9') ||
 911	    c == '/' ||
 912	    c == '-' ||
 913	    c == '_' ||
 914	    c == '.'
 915	  })
 916	}
